import { Component, Type } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { MatFormField, MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { By } from '@angular/platform-browser';
import { provideNoopAnimations } from '@angular/platform-browser/animations';
import { provideUiDefaults } from '../ui-defaults.provider';
import { FormLayoutComponent } from './form-layout.component';

@Component({
  imports: [FormLayoutComponent, MatFormFieldModule, MatInputModule],
  template: `<form-layout
    ><mat-form-field><input matInput /></mat-form-field
  ></form-layout>`,
})
class DefaultHostComponent {}

@Component({
  imports: [FormLayoutComponent, MatFormFieldModule, MatInputModule],
  template: `<form-layout appearance="outline"
    ><mat-form-field><input matInput /></mat-form-field
  ></form-layout>`,
})
class StaticOverrideHostComponent {}

@Component({
  selector: 'test-field',
  imports: [MatFormFieldModule, MatInputModule],
  template: `<mat-form-field><input matInput /></mat-form-field>`,
})
class FieldComponent {}

@Component({
  imports: [FormLayoutComponent, FieldComponent],
  template: `<form-layout appearance="outline"><test-field /></form-layout>`,
})
class ChildOverrideHostComponent {}

function renderField(host: Type<unknown>): MatFormField {
  TestBed.configureTestingModule({
    imports: [host],
    providers: [
      provideNoopAnimations(),
      provideUiDefaults({ formFieldAppearance: 'fill', subscriptSizing: 'dynamic' }),
    ],
  });
  const fixture = TestBed.createComponent(host);
  fixture.detectChanges();
  return fixture.debugElement.query(By.directive(MatFormField)).componentInstance;
}

describe('FormLayoutComponent', () => {
  it('adds grid class to host element', () => {
    TestBed.configureTestingModule({
      imports: [FormLayoutComponent],
    });

    const fixture = TestBed.createComponent(FormLayoutComponent);
    fixture.detectChanges();

    expect(fixture.nativeElement.classList.contains('form-layout-grid')).toBeTrue();
  });

  it('uses the application defaults from provideUiDefaults', () => {
    const field = renderField(DefaultHostComponent);

    expect(field.appearance).toBe('fill');
    expect(field.subscriptSizing).toBe('dynamic');
  });

  it('lets a single form override the appearance with a static attribute', () => {
    const field = renderField(StaticOverrideHostComponent);

    expect(field.appearance).toBe('outline');
    expect(field.subscriptSizing).toBe('dynamic');
  });

  it('applies the override to fields rendered by child components (editables)', () => {
    const field = renderField(ChildOverrideHostComponent);

    expect(field.appearance).toBe('outline');
  });
});
